#include <algorithm>
#include <queue>
#include <string>
#include <vector>

using Graph = std::vector<std::vector<int>>;

static std::vector<int> bfs(const Graph& adj, int source, std::vector<int>* parent)
{
    std::vector<int> dist(adj.size(), -1);
    std::queue<int> q;
    dist[source] = 0;
    q.push(source);
    while (!q.empty())
    {
        int u = q.front();
        q.pop();
        for (int v : adj[u])
            if (dist[v] == -1)
            {
                dist[v] = dist[u] + 1;
                if (parent) (*parent)[v] = u;
                q.push(v);
            }
    }
    return dist;
}

std::vector<int> distances(const Graph& adj, int source) { return bfs(adj, source, nullptr); }

std::vector<int> shortestPath(const Graph& adj, int from, int to)
{
    std::vector<int> parent(adj.size(), -1);
    std::vector<int> dist = bfs(adj, from, &parent);
    if (dist[to] == -1) return {};
    std::vector<int> path;
    for (int v = to; v != from; v = parent[v]) path.push_back(v);
    path.push_back(from);
    std::reverse(path.begin(), path.end());
    return path;
}

int components(const Graph& adj)
{
    std::vector<bool> seen(adj.size(), false);
    int count = 0;
    for (std::size_t s = 0; s < adj.size(); ++s)
    {
        if (seen[s]) continue;
        ++count;
        std::queue<int> q;
        q.push(static_cast<int>(s));
        seen[s] = true;
        while (!q.empty())
        {
            int u = q.front();
            q.pop();
            for (int v : adj[u])
                if (!seen[v]) { seen[v] = true; q.push(v); }
        }
    }
    return count;
}

bool isBipartite(const Graph& adj)
{
    std::vector<int> colour(adj.size(), -1);
    for (std::size_t s = 0; s < adj.size(); ++s)
    {
        if (colour[s] != -1) continue;
        colour[s] = 0;
        std::queue<int> q;
        q.push(static_cast<int>(s));
        while (!q.empty())
        {
            int u = q.front();
            q.pop();
            for (int v : adj[u])
            {
                if (colour[v] == -1) { colour[v] = 1 - colour[u]; q.push(v); }
                else if (colour[v] == colour[u]) return false;
            }
        }
    }
    return true;
}

int nearestExitSteps(const std::vector<std::string>& grid)
{
    int rows = static_cast<int>(grid.size());
    int cols = rows ? static_cast<int>(grid[0].size()) : 0;
    std::vector<std::vector<int>> dist(rows, std::vector<int>(cols, -1));
    std::queue<std::pair<int, int>> q;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c)
            if (grid[r][c] == 'E') { dist[r][c] = 0; q.push({ r, c }); }
    const int dr[] = { -1, 1, 0, 0 }, dc[] = { 0, 0, -1, 1 };
    while (!q.empty())
    {
        auto [r, c] = q.front();
        q.pop();
        for (int d = 0; d < 4; ++d)
        {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == '#' || dist[nr][nc] != -1) continue;
            dist[nr][nc] = dist[r][c] + 1;
            q.push({ nr, nc });
        }
    }
    int worst = 0;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c)
            if (grid[r][c] == 'P')
            {
                if (dist[r][c] == -1) return -1;
                worst = std::max(worst, dist[r][c]);
            }
    return worst;
}

