static Graph undirected(int n, const std::vector<std::pair<int, int>>& edges)
{
    Graph g(n);
    for (auto [a, b] : edges) { g[a].push_back(b); g[b].push_back(a); }
    return g;
}

TEST("distances") {
    Graph g = undirected(8, { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 }, { 3, 4 }, { 4, 5 }, { 2, 6 }, { 6, 5 } });
    CHECK_EQ(distances(g, 0), (std::vector<int>{ 0, 1, 1, 2, 3, 3, 2, -1 }));
    CHECK_EQ(distances(g, 7), (std::vector<int>{ -1, -1, -1, -1, -1, -1, -1, 0 }));
}
TEST("shortest paths") {
    Graph g = undirected(8, { { 0, 1 }, { 0, 2 }, { 1, 3 }, { 2, 3 }, { 3, 4 }, { 4, 5 }, { 2, 6 }, { 6, 5 } });
    CHECK_EQ(shortestPath(g, 0, 5), (std::vector<int>{ 0, 2, 6, 5 }));
    CHECK_EQ(shortestPath(g, 0, 3), (std::vector<int>{ 0, 1, 3 }));
    CHECK_EQ(shortestPath(g, 4, 4), (std::vector<int>{ 4 }));
    CHECK(shortestPath(g, 0, 7).empty());
    Graph directed(4);
    directed[0] = { 1 }; directed[1] = { 2 }; directed[2] = { 3 };
    CHECK_EQ(shortestPath(directed, 0, 3), (std::vector<int>{ 0, 1, 2, 3 }));
    CHECK(shortestPath(directed, 3, 0).empty());
}
TEST("components") {
    CHECK_EQ(components(undirected(6, { { 0, 1 }, { 2, 3 }, { 3, 4 } })), 3);
    CHECK_EQ(components(undirected(3, {})), 3);
    CHECK_EQ(components(Graph{}), 0);
    std::vector<std::pair<int, int>> chain;
    for (int i = 1; i < 200000; ++i) if (i % 1000 != 0) chain.push_back({ i - 1, i });
    CHECK_EQ(components(undirected(200000, chain)), 200);
}
TEST("bipartite") {
    CHECK(isBipartite(undirected(4, { { 0, 1 }, { 1, 2 }, { 2, 3 }, { 3, 0 } })));
    CHECK(!isBipartite(undirected(3, { { 0, 1 }, { 1, 2 }, { 2, 0 } })));
    CHECK(isBipartite(undirected(5, { { 0, 1 }, { 3, 4 } })));
    CHECK(!isBipartite(undirected(7, { { 0, 1 }, { 2, 3 }, { 3, 4 }, { 4, 5 }, { 5, 6 }, { 6, 2 } })));
}
TEST("nearest exits") {
    CHECK_EQ(nearestExitSteps({ "E..P", "....", "P..E" }), 2);
    CHECK_EQ(nearestExitSteps({ "P#E" }), -1);
    CHECK_EQ(nearestExitSteps({ "...", ".E." }), 0);
    CHECK_EQ(nearestExitSteps({ "E.#.....",
                                ".##.###.",
                                "....#...",
                                "#.#.#.#.",
                                "..#...#P" }), 15);
    std::vector<std::string> big(300, std::string(300, 'P'));
    big[0][0] = 'E';
    big[299][299] = 'E';
    CHECK_EQ(nearestExitSteps(big), 299);
}

